{
  "type": "object",
  "properties": {
    "data": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/CbuaeBalance"
      },
      "description": "Primary data for the resource"
    },
    "meta": {
      "$ref": "#/components/schemas/Meta"
    }
  },
  "description": "List of Balances for an Account."
}

{
  "type": "object",
  "properties": {
    "accountId": {
      "description": "A unique and immutable identifier produced by the financial institution to identify the account resource.This identifier has no meaning to the account owner (User 1).",
      "type": "string"
    },
    "creditDebitIndicator": {
      "$ref": "#/components/schemas/AECreditDebitIndicator"
    },
    "balanceType": {
      "$ref": "#/components/schemas/CbuaeBalanceType"
    },
    "timestamp": {
      "$ref": "#/components/schemas/AEBalanceCheckDateTime"
    },
    "amount": {
      "$ref": "#/components/schemas/OBActiveOrHistoricCurrencyAndAmount_8"
    },
    "creditLines": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/CbuaeCreditLine"
      },
      "description": "Set of elements used to provide details of credit lines available for the account."
    },
    "components": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEAmountWithCategorization"
      }
    }
  },
  "required": [
    "accountId",
    "balanceType",
    "amount",
    "creditDebitIndicator",
    "timestamp"
  ],
  "description": "The properties of a given balance."
}

{
  "description": "Indicates whether a given balance, transaction, or summarized amount is a credit or a debit.",
  "type": "string",
  "enum": [
    "Credit",
    "Debit"
  ]
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/AEDateTime"
    },
    {
      "description": "Indicates the date (and time) that the account balance was checked"
    }
  ]
}

{
  "type": "object",
  "required": [
    "amount",
    "currency"
  ],
  "properties": {
    "amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
    },
    "currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
    }
  },
  "description": "The amount and currency code for a given payment or transaction."
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "SAR"
}

{
  "description": "Set of elements used to provide details on the credit line.",
  "type": "object",
  "required": [
    "included",
    "creditType",
    "amount"
  ],
  "properties": {
    "included": {
      "description": "Boolean flag to Indicate whether or not a credit line is included in the balance of the account.",
      "type": "boolean"
    },
    "creditType": {
      "description": "Type of credit line provided to the account. The enumerations values are defined as follows.\n\n- Available: The amount of credit limit available to the account holder\n- Credit: The amount of a credit limit that has been agreed with the account holder\n- Emergency: The amount of an arranged lending limit that can be borrowed on top of pre-agreed lending, that has been agreed with the account holder\n- Pre-Agreed: The amount of an arranged lending limit that has been agreed with the account holder\n- Temporary: The amount of a temporary lending limit that has been agreed with the account holder\n",
      "type": "string",
      "enum": [
        "Available",
        "Credit",
        "Emergency",
        "Pre-Agreed",
        "Temporary"
      ]
    },
    "amount": {
      "$ref": "#/components/schemas/OBActiveOrHistoricCurrencyAndAmount_8"
    }
  }
}

{
  "type": "object",
  "required": [
    "BalanceCategory",
    "Amount"
  ],
  "properties": {
    "BalanceCategory": {
      "$ref": "#/components/schemas/AEBalanceCategory"
    },
    "BalanceDescription": {
      "description": "Allows a description to provided of the balance to identify the specific Shari’ah compliant charges, payments, and rewards made which can affect the balance.",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Amount": {
      "description": "The value of the categorized balance, incorporating `Amount` and `Currency`.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "totalPages": {
      "type": "number",
      "description": "The number of expected pages for the query.\n"
    },
    "totalRecords": {
      "type": "number",
      "description": "The total number of records in the full set.\n"
    }
  },
  "description": "Metadata relevant to the resource."
}

{
